44→          </div>
45→        </div>
46→
47→        {/* Image-only hover overlay */}
48→        {!showText && (
49→          <div className={styles.hoverOverlay}>
50→            <span className={styles.hoverTitle}>{project.title}</span>
51→          </div>
52→        )}
53→      </div>
