  1→.card {
  2→  cursor: pointer;
  3→  display: block;
  4→}
  5→
  6→.imageContainer {
  7→  border-radius: var(--img-radius);
  8→  overflow: hidden;
  9→  position: relative;
 10→}
 11→
 12→/* --- Scroll-driven card reveal --- */
 13→
 14→@keyframes cardReveal {
 15→  from {
 16→    clip-path: inset(0 0 100% 0);
 17→    opacity: 0;
 18→  }
 19→  to {
 20→    clip-path: inset(0 0 0% 0);
 21→    opacity: 1;
 22→  }
 23→}
 24→
 25→@keyframes cardScale {
 26→  from { transform: scale(1.06); }
 27→  to { transform: scale(1); }
 28→}
 29→
 30→@keyframes textFadeIn {
 31→  from {
 32→    opacity: 0;
 33→    transform: translateY(10px);
 34→  }
 35→  to {
 36→    opacity: 1;
 37→    transform: translateY(0);
 38→  }
 39→}
 40→
 41→.clipWrapper {
 42→  animation: cardReveal linear both;
 43→  animation-timeline: view();
 44→  animation-range: entry 0% entry 60%;
 45→}
 46→
 47→.scaleWrapper {
 48→  animation: cardScale linear both;
 49→  animation-timeline: view();
 50→  animation-range: entry 0% entry 90%;
 51→}
 52→
 53→/* Image-only hover overlay */
 54→.hoverOverlay {
 55→  position: absolute;
 56→  bottom: 0;
 57→  left: 0;
 58→  right: 0;
 59→  top: 0;
 60→  border-radius: var(--img-radius);
 61→  display: flex;
 62→  align-items: flex-end;
 63→  padding: 20px;
 64→  background: transparent;
 65→  opacity: 0;
 66→  transition: all 400ms var(--ease);
 67→  pointer-events: none;
 68→}
 69→
 70→.card:hover .hoverOverlay {
 71→  background: linear-gradient(to top, rgba(0, 0, 0, 0.5) 0%, transparent 60%);
 72→  opacity: 1;
 73→}
 74→
 75→.hoverTitle {
 76→  color: #fff;
 77→  font-size: 14px;
 78→  font-weight: 400;
 79→  letter-spacing: 0.02em;
 80→  transform: translateY(8px);
 81→  transition: transform 400ms var(--ease-out);
 82→}
 83→
 84→.card:hover .hoverTitle {
 85→  transform: translateY(0);
 86→}
 87→
 88→/* Text block */
 89→.textBlock {
 90→  margin-top: 14px;
 91→  padding-bottom: 38px;
 92→  position: relative;
 93→  animation: textFadeIn linear both;
 94→  animation-timeline: view();
 95→  animation-range: entry 15% entry 55%;
 96→}
 97→
 98→.title {
 99→  font-size: 16px;
100→  font-weight: 400;
101→  margin: 0 0 3px;
102→  color: var(--text);
103→  letter-spacing: normal;
104→  line-height: 1.35;
105→}
106→
107→.desc {
108→  font-size: 15px;
109→  font-weight: 400;
110→  margin: 0;
111→  color: var(--muted);
112→  letter-spacing: normal;
113→  line-height: 1.35;
114→}
115→
116→/* Elevator metatags */
117→.metatagWrapper {
118→  position: absolute;
119→  bottom: 0;
120→  left: 0;
121→  right: 0;
122→  height: 30px;
123→  overflow: hidden;
124→}
125→
126→.metatagInner {
127→  display: flex;
128→  flex-wrap: wrap;
129→  gap: 8px;
130→  transform: translateY(-110%);
131→  opacity: 0;
132→  transition:
133→    transform 350ms var(--ease),
134→    opacity 250ms var(--ease);
135→}
136→
137→.card:hover .metatagInner {
138→  transform: translateY(0);
139→  opacity: 1;
140→  transition:
141→    transform 350ms var(--ease-out),
142→    opacity 250ms var(--ease-out);
143→}
144→
145→/* Image desaturation */
146→.imageDefault {
147→  filter: saturate(0.85);
148→  transition: filter 400ms var(--ease);
149→}
150→
151→.card:hover .imageDefault {
152→  filter: saturate(1) brightness(1.02);
153→}
154→
155→/* Fallback: browsers without scroll-driven animation support */
156→@supports not (animation-timeline: view()) {
157→  .clipWrapper {
158→    clip-path: none;
159→    opacity: 1;
160→    animation: none;
161→  }
162→  .scaleWrapper {
163→    transform: none;
164→    animation: none;
165→  }
166→  .textBlock {
167→    opacity: 1;
168→    transform: none;
169→    animation: none;
170→  }
171→}
172→
173→/* Accessibility: reduced motion */
174→@media (prefers-reduced-motion: reduce) {
175→  .clipWrapper,
176→  .scaleWrapper,
177→  .textBlock {
178→    animation: none;
179→    clip-path: none;
180→    opacity: 1;
181→    transform: none;
182→  }
183→}
