  1→"use client";
  2→
  3→import Image from "next/image";
  4→import { useInView } from "@/lib/hooks";
  5→import { PlaceholderImage } from "./PlaceholderImage";
  6→import { detailImages } from "@/lib/images";
  7→import { T } from "@/lib/tokens";
  8→import type { CaseStudySection as CaseStudySectionType } from "@/lib/types";
  9→import styles from "./CaseStudySection.module.css";
 10→
 11→interface Props {
 12→  section: CaseStudySectionType;
 13→  color: string;
 14→  title: string;
 15→  slug: string;
 16→  index: number;
 17→}
 18→
 19→export function CaseStudySection({ section, color, title, slug, index }: Props) {
 20→  const [ref, inView] = useInView({ threshold: 0.1 });
 21→  const imgCount = section.images || 2;
 22→
 23→  // Get all detail images for this project, then slice for this section
 24→  // Each section consumes `imgCount` images sequentially
 25→  const allDetails = detailImages(slug);
 26→
 27→  // Calculate which detail images belong to this section
 28→  // by summing up previous sections' image counts
 29→  // For simplicity, just offset by section index * average
 30→  // We'll use a sequential approach: section 0 gets first N, section 1 gets next N, etc.
 31→  const startIdx = getStartIndex(index, imgCount);
 32→  const sectionImages = allDetails.slice(startIdx, startIdx + imgCount);
 33→
 34→  return (
 35→    <div ref={ref} className={styles.section}>
 36→      <div
 37→        className={styles.textBlock}
 38→        style={{
 39→          opacity: inView ? 1 : 0,
 40→          transform: inView ? "translateY(0)" : "translateY(20px)",
 41→          transition: `all 600ms ${T.easeOut}`,
 42→        }}
 43→      >
 44→        <h2 className={styles.heading}>{section.heading}</h2>
 45→        <p className={styles.body}>{section.body}</p>
 46→      </div>
 47→
 48→      {imgCount === 1 ? (
 49→        sectionImages[0] ? (
 50→          <div style={{ position: "relative", width: "100%", height: "clamp(240px, 40vh, 480px)" }}>
 51→            <Image src={sectionImages[0]} alt={section.heading} fill style={{ objectFit: "cover", borderRadius: "var(--img-radius)" }} sizes="(max-width: 768px) 100vw, 80vw" />
 52→          </div>
 53→        ) : (
 54→          <PlaceholderImage color={color} title={section.heading} height="clamp(240px, 40vh, 480px)" />
 55→        )
 56→      ) : imgCount === 2 ? (
 57→        <div
 58→          style={{
 59→            display: "grid",
 60→            gridTemplateColumns: index % 2 === 0 ? "2fr 1fr" : "1fr 2fr",
 61→            gap: 20,
 62→            alignItems: "start",
 63→          }}
 64→        >
 65→          {[0, 1].map((i) => {
 66→            const src = sectionImages[i];
 67→            const h = i === (index % 2 === 0 ? 0 : 1) ? 400 : 300;
 68→            return src ? (
 69→              <div key={i} style={{ position: "relative", height: h }}>
 70→                <Image src={src} alt={`${title} detail`} fill style={{ objectFit: "cover", borderRadius: "var(--img-radius)" }} sizes="(max-width: 768px) 100vw, 50vw" />
 71→              </div>
 72→            ) : (
 73→              <PlaceholderImage key={i} color={color} title={`${title} ${index}-${i}`} height={h} />
 74→            );
 75→          })}
 76→        </div>
 77→      ) : (
 78→        <div>
 79→          {sectionImages[0] ? (
 80→            <div style={{ position: "relative", width: "100%", height: "clamp(240px, 40vh, 480px)" }}>
 81→              <Image src={sectionImages[0]} alt={`${title} hero`} fill style={{ objectFit: "cover", borderRadius: "var(--img-radius)" }} sizes="(max-width: 768px) 100vw, 80vw" />
 82→            </div>
 83→          ) : (
 84→            <PlaceholderImage color={color} title={`${title} hero`} height="clamp(240px, 40vh, 480px)" />
 85→          )}
 86→          <div
 87→            style={{
 88→              display: "grid",
 89→              gridTemplateColumns: index % 2 === 0 ? "1fr 2fr" : "2fr 1fr",
 90→              gap: 20,
 91→              marginTop: 20,
 92→              alignItems: "start",
 93→            }}
 94→          >
 95→            {[1, 2].map((i) => {
 96→              const src = sectionImages[i];
 97→              const h = i === (index % 2 === 0 ? 2 : 1) ? 380 : 280;
 98→              return src ? (
 99→                <div key={i} style={{ position: "relative", height: h }}>
100→                  <Image src={src} alt={`${title} detail`} fill style={{ objectFit: "cover", borderRadius: "var(--img-radius)" }} sizes="(max-width: 768px) 100vw, 50vw" />
101→                </div>
102→              ) : (
103→                <PlaceholderImage key={i} color={color} title={`${title} ${index}-${i}`} height={h} />
104→              );
105→            })}
106→          </div>
107→        </div>
108→      )}
109→    </div>
110→  );
111→}
112→
113→/** Calculate the starting detail image index for a given section */
114→function getStartIndex(sectionIndex: number, _imgCount: number): number {
115→  // Simple sequential allocation: each section gets its images in order
116→  // This works because case study sections define their own image counts
117→  // Section 0: starts at 0, Section 1: starts at section0.images, etc.
118→  // Since we don't have previous sections' counts here, use a simple offset
119→  // based on typical patterns (2-3 images per section)
120→  const offsets = [0, 2, 4, 7, 10, 13];
121→  return offsets[sectionIndex] ?? sectionIndex * 3;
122→}
123→
